function sql(value) {
  if (value === undefined || value === null || value === '') return 'NULL';
  return `'${String(value).replace(/'/g, "''")}'`;
}

const body = $json.body || {};
const assetId = String(body.assetId || body.asset_id || '').trim();
const reviewNotes = String(body.reviewNotes || body.review_notes || 'Marked as selected via Asset Review API').trim();
const baseUrl = String(body.baseUrl || body.base_url || 'http://192.168.0.194:9000').replace(/\/$/, '');

const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

if (!uuidRegex.test(assetId)) {
  return {
    json: {
      skipQuery: true,
      ok: false,
      selected: false,
      statusCode: 400,
      error: assetId ? 'Invalid assetId. Expected a UUID.' : 'assetId is required',
      assetId: assetId || null
    }
  };
}

const query = `
UPDATE canonical_asset_registry
SET
  is_canonical = false,
  status = 'selected',
  review_notes = ${sql(reviewNotes)},
  metadata = jsonb_set(
    jsonb_set(
      COALESCE(metadata, '{}'::jsonb),
      '{status}',
      '"selected"'::jsonb,
      true
    ),
    '{isCanonical}',
    'false'::jsonb,
    true
  )
WHERE asset_id = ${sql(assetId)}
  AND COALESCE(is_canonical, false) = false
  AND COALESCE(status, '') <> 'canonical'
RETURNING
  asset_id,
  sha256,
  avatar,
  asset_type,
  scene,
  bucket,
  object_path,
  mime_type,
  status,
  is_canonical,
  canonical_group,
  review_notes,
  created_at;
`;

return {
  json: {
    skipQuery: false,
    query,
    assetId,
    baseUrl
  }
};

const params = $('Build Select Query').first().json;
const row = $input.first()?.json ?? {};

if (!row.asset_id || !row.bucket || !row.object_path) {
  return [{
    json: {
      ok: false,
      selected: false,
      statusCode: 404,
      error: 'Asset not found, already canonical, or selection failed',
      assetId: params.assetId
    }
  }];
}

const baseUrl = (params.baseUrl || 'http://192.168.0.194:9000').replace(/\/$/, '');

const asset = {
  assetId: row.asset_id,
  avatar: row.avatar,
  scene: row.scene,
  assetType: row.asset_type,
  status: row.status,
  isCanonical: row.is_canonical,
  canonicalGroup: row.canonical_group,
  bucket: row.bucket,
  objectPath: row.object_path,
  url: `${baseUrl}/${row.bucket}/${row.object_path}`,
  mimeType: row.mime_type,
  sha256: row.sha256,
  reviewNotes: row.review_notes,
  createdAt: row.created_at
};

return [{
  json: {
    ok: true,
    selected: true,
    statusCode: 200,
    asset,
    ...asset
  }
}];
